package jobctl

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"text/template"

	"github.com/WilliamsStudentsOnline/wso-go/jobs/registry"
)

const unitPrefix = "wso-job-"

var serviceTmpl = template.Must(template.New("service").Parse(`##### WSO job: {{.Name}} #####
# Generated by wso-jobctl gen-units — do not edit by hand
[Unit]
Description=WSO job: {{.Name}}{{if .Description}} — {{.Description}}{{end}}
After=network-online.target

[Service]
Type=oneshot
User={{.User}}
Group={{.Group}}
ExecStart={{.ExecStart}}
{{if .RuntimeMaxSec}}RuntimeMaxSec={{.RuntimeMaxSec}}
{{end}}{{if .MemoryMax}}MemoryMax={{.MemoryMax}}
{{end}}
[Install]
WantedBy=multi-user.target
`))

var timerTmpl = template.Must(template.New("timer").Parse(`##### WSO job timer: {{.Name}} #####
# Generated by wso-jobctl gen-units — do not edit by hand
[Unit]
Description=WSO job timer: {{.Name}}
Requires={{.ServiceFile}}

[Timer]
OnCalendar={{.OnCalendar}}
Persistent=true
Unit={{.ServiceFile}}

[Install]
WantedBy=timers.target
`))

type serviceData struct {
	Name          string
	Description   string
	User          string
	Group         string
	ExecStart     string
	RuntimeMaxSec int
	MemoryMax     string
}

type timerData struct {
	Name        string
	ServiceFile string
	OnCalendar  string
}

// GenUnits writes systemd unit files for every registered job into outDir
// and removes stale wso-job-* units that are no longer in the registry.
// Jobs with a Schedule get a .timer; every job that can build default args
// gets a .service. Jobs that require params with no defaults are skipped
// (those are started as transient units later).
func GenUnits(r *registry.Registry, outDir string) error {
	if err := os.MkdirAll(outDir, 0755); err != nil {
		return fmt.Errorf("mkdir %s: %w", outDir, err)
	}

	wanted := map[string]struct{}{}

	for _, j := range r.All() {
		args, err := j.BuildArgs(nil)
		if err != nil {
			// required params without defaults — no static service unit
			continue
		}

		execStart, err := formatExecStart(j.Binary, args)
		if err != nil {
			return fmt.Errorf("job %s: %w", j.Name, err)
		}

		svcName := j.ServiceFile()
		svcPath := filepath.Join(outDir, svcName)
		f, err := os.Create(svcPath)
		if err != nil {
			return err
		}
		err = serviceTmpl.Execute(f, serviceData{
			Name:          j.Name,
			Description:   j.Description,
			User:          j.EffectiveUser(),
			Group:         j.EffectiveGroup(),
			ExecStart:     execStart,
			RuntimeMaxSec: j.RuntimeMaxSec,
			MemoryMax:     j.MemoryMax,
		})
		closeErr := f.Close()
		if err != nil {
			return fmt.Errorf("write %s: %w", svcPath, err)
		}
		if closeErr != nil {
			return closeErr
		}
		wanted[svcName] = struct{}{}

		if j.Schedule == nil {
			continue
		}

		timerName := j.TimerFile()
		timerPath := filepath.Join(outDir, timerName)
		tf, err := os.Create(timerPath)
		if err != nil {
			return err
		}
		err = timerTmpl.Execute(tf, timerData{
			Name:        j.Name,
			ServiceFile: svcName,
			OnCalendar:  j.Schedule.OnCalendar,
		})
		closeErr = tf.Close()
		if err != nil {
			return fmt.Errorf("write %s: %w", timerPath, err)
		}
		if closeErr != nil {
			return closeErr
		}
		wanted[timerName] = struct{}{}
	}

	return pruneStale(outDir, wanted)
}

func formatExecStart(binary string, args []string) (string, error) {
	parts := make([]string, 0, 1+len(args))
	parts = append(parts, binary)
	for _, a := range args {
		if strings.ContainsAny(a, " \t\n\"'\\") {
			return "", fmt.Errorf("arg %q needs quoting; unsupported for now", a)
		}
		parts = append(parts, a)
	}
	return strings.Join(parts, " "), nil
}

func pruneStale(outDir string, wanted map[string]struct{}) error {
	entries, err := os.ReadDir(outDir)
	if err != nil {
		return err
	}
	for _, e := range entries {
		name := e.Name()
		if !strings.HasPrefix(name, unitPrefix) {
			continue
		}
		if !strings.HasSuffix(name, ".service") && !strings.HasSuffix(name, ".timer") {
			continue
		}
		if _, ok := wanted[name]; ok {
			continue
		}
		if err := os.Remove(filepath.Join(outDir, name)); err != nil {
			return fmt.Errorf("prune %s: %w", name, err)
		}
	}
	return nil
}
